var e={"profile.title":`Your pseudo`,"profile.desc":`Used when your web messages are copied to Telegram (not shown under your messages in the sessions).`,"profile.name":`Name`,"profile.nameDesc":`Up to 32 characters. Empty: no pseudo.`,"profile.namePlaceholder":`e.g. Alex`,"profile.color":`Color`,"profile.colorDesc":`The color of your badge.`,"profile.emoji":`Emoji`,"profile.emojiDesc":`Shown in your badge instead of your initials (optional).`,"profile.preview":`Preview`,"profile.previewText":`Hi! Ready when you are.`,"profile.you":`You`,"register.title":`Harness Maxxing team`,"register.desc":`All optional. What this server tells the authors of Harness Maxxing, and how to stop.`,"register.email":`Email (optional)`,"register.emailPlaceholder":`you@example.com`,"register.emailDesc":`Only to warn you about a security issue or a breaking change. Never shared, never sold.`,"register.emailInvalid":`This does not look like an email address.`,"register.news":`Also send me the product news`,"register.newsDesc":`New features, a few times a month at most. Unsubscribe here at any time.`,"register.count":`Help count the installations (anonymous)`,"register.countDesc":`Once a day, a random number and the version of Harness Maxxing. Nothing else: no name, no IP, no content.`,"register.privacy":`Sent to api.harness-maxxing.com. Your pseudo and language are sent only with an email. Unchecking everything stops it: we never contact this server again.`,"register.statusOff":`This server tells the authors nothing.`,"register.statusOn":`Registered. One signal a day (version).`,"register.statusPending":`Not sent yet: it will be at the next daily signal.`,"register.statusError":`Could not reach the authors: {error}. It will try again tomorrow.`,"register.stop":`Stop, don't contact me`,"license.title":`Enterprise license (optional)`,"license.desc":`Harness Maxxing is free for yourself and for an organisation that uses it for its own needs. A key is only for the companies that need one; it changes nothing in how it works.`,"license.read":`Read the license`,"license.whoTitle":`Who needs a key?`,"license.who1":`An organisation using it for its affiliates, group companies or clients.`,"license.who2":`A paid offer that includes it: resale, hosting, paid installation or support.`,"license.whoNot":`Nobody else: individuals, freelancers and organisations for their own needs have nothing to do.`,"license.get":`Ask for an Enterprise license`,"license.yours":`Your key`,"license.key":`License key`,"license.keyDesc":`Checked by harness-maxxing.com (one key = one server). Nothing else changes: updates keep coming from GitHub.`,"license.invalid":`A key looks like HM-XXXX-XXXX-XXXX-XXXX.`,"license.save":`Save the key`,"license.none":`No key recorded: that is normal unless you are in one of the cases above.`,"license.active":`Key {key} ({kind})`,"license.until":`until {date}`,"license.remove":`Remove the key`,"license.removeDesc":`Frees its place for another server.`,"license.onbToggle":`I have an Enterprise license key`,"license.onbToggleDesc":`Optional, only for the companies that have one. Can be changed later in Settings -> License.`,"tint.neutral":`Neutral`,"tint.tinted":`Accent tint`,"fonts.group.modern":`Modern`,"fonts.group.character":`With character`,"fonts.group.rounded":`Rounded`,"fonts.group.serif":`Serif`,"fonts.group.readable":`Easy to read`,"fonts.group.mono":`Monospace`,"fonts.group.system":`This device`,"density.comfortable":`Comfortable`,"density.compact":`Compact`,"accent.clay":`Orange`,"accent.blue":`Blue`,"accent.violet":`Purple`,"accent.green":`Green`,"accent.amber":`Yellow`,"accent.rose":`Red`,"features.browser":`In this browser`,"features.browserDesc":`Saved in this browser only.`,"features.server":`For everyone`,"features.serverDesc":`Saved on the server: every browser and device gets them.`,"features.telegramFirst":`Link Telegram first:`,"security.change":`Change password`,"security.changeDesc":`Changing the password signs out every other device.`,"security.current":`Current password`,"security.currentRequired":`Enter your current password.`,"security.currentWrong":`The current password is wrong.`,"security.update":`Update password`,"security.changed":`Password changed`,"security.changedDesc":`Other devices have been signed out.`,"security.sessions":`Signed-in devices`,"security.sessionsDesc":`Sign-in alerts can be sent to Telegram (Settings › Telegram).`,"security.everywhere":`To sign out everywhere, change your password: every existing session cookie stops working immediately.`,"telegram.setup":`Set up Telegram`,"telegram.setupDesc":`About two minutes. You need the Telegram app on your phone or computer.`,"telegram.sub.bot":`Bot`,"telegram.sub.link":`Link`,"telegram.sub.threads":`Threads`,"telegram.bf1":`In Telegram, open`,"telegram.bf2":`Send the command:`,"telegram.bf3":`Choose a display name, then a username that ends with "bot" (e.g. acme_maxxing_bot).`,"telegram.bf4":`BotFather replies with a token like 123456789:AAH…: copy it and paste it below.`,"telegram.token":`Bot token`,"telegram.tokenHint":`Kept on this server. Anyone with the token controls the bot.`,"telegram.tokenRequired":`Paste the token from BotFather.`,"telegram.tokenInvalid":`Telegram rejected this token.`,"telegram.verify":`Verify token`,"telegram.botOk":`Bot verified`,"telegram.linkIntro":`Now link your Telegram account: only the linked chat can talk to Harness.`,"telegram.link":`Link my Telegram`,"telegram.qr":`QR code to open the bot`,"telegram.scan":`Scan with your phone`,"telegram.openAndStart":`Open the bot and press Start. This page updates by itself once the link is made.`,"telegram.openTelegram":`Open in Telegram`,"telegram.waiting":`Waiting for /start…`,"telegram.linked":`Linked!`,"telegram.manualCode":`Or send this message to the bot:`,"telegram.chatLinked":`Chat linked`,"telegram.threadsIntro":`Each open session gets its own thread (plus Crons and Alerts). Archive a session and its thread goes away; write in the main chat to start a new one.`,"telegram.createThreads":`Create threads`,"telegram.syncAgain":`Sync again`,"telegram.created":`{count} threads created`,"telegram.created#one":`{count} thread created`,"telegram.topicsOff":`Threads are disabled for this bot`,"telegram.topicsOff1":`Open @BotFather and send /mybots, then pick your bot.`,"telegram.topicsOff2":`Bot Settings › Threaded Mode › turn it on.`,"telegram.topicsOff3":`Come back here and press "Sync again". Until then, everything goes to the main chat.`,"telegram.noThreads":`No threads yet.`,"telegram.thread.general":`General`,"telegram.thread.crons":`Cron reports`,"telegram.thread.alerts":`Alerts`,"telegram.status":`Status`,"telegram.gateway":`Gateway`,"telegram.running":`Running`,"telegram.stopped":`Stopped`,"telegram.bot":`Bot`,"telegram.chat":`Linked chat`,"telegram.test":`Send a test message`,"telegram.testSent":`Test message sent`,"telegram.behaviour":`Behaviour`,"telegram.notifyCrons":`Cron reports`,"telegram.notifyCronsDesc":`Post cron results in the Crons thread (per-job settings apply).`,"telegram.loginAlerts":`Sign-in alerts`,"telegram.loginAlertsDesc":`Message on every sign-in and loud alert after repeated wrong passwords.`,"telegram.replyMode":`Replies`,"telegram.replyModeDesc":`Live progress: one status message updated while Harness works (its task list and each step), folded into a summary at the end. Or only the final answer.`,"telegram.reply.final":`Final answer`,"telegram.reply.progress":`Live progress`,"trash.title":`Trash`,"trash.desc":`Deleted files, topics, projects and sessions. Restore them where they were, or delete them for good. Items older than {days} days are removed automatically.`,"trash.kind.file":`file`,"trash.kind.folder":`folder`,"trash.kind.topic":`topic`,"trash.kind.project":`project`,"trash.kind.session":`session`,"trash.kind.previous_versions":`previous versions`,"trash.sessions":`{count} sessions`,"trash.root":`workspace root`,"trash.restore":`Restore`,"trash.restored":`Restored to {path}`,"trash.deleteForever":`Delete forever`,"trash.deleteConfirm":`Delete “{name}” forever?`,"trash.deleteDesc":`This cannot be undone.`,"trash.empty":`Empty the trash`,"trash.emptyConfirm":`Empty the trash?`,"trash.emptied":`Trash emptied`,"trash.none":`The trash is empty`,"trash.noneDesc":`Deleted files, topics and sessions land here.`,"packs.title":`Starter projects`,"packs.desc":`Ready-made projects for a kind of work: each topic already knows the job (a playbook) and asks you a few questions at the first session. No fake data. Add a pack as many times as you like: each time it is a new project (ecommerce-2 for a second store...). Nothing existing is ever overwritten.`,"packs.restore":`Put back`,"packs.restored":`{count} files put back`,"packs.nothingMissing":`Nothing was missing`,"packs.add":`Add`,"packs.added":`Added`,"packs.complete":`Add the missing topics`,"packs.jobs":`Scheduled jobs created disabled: {list}`,"packs.done":`{name} added ({count} topics)`,"packs.doneMany":`{count} projects added`,"packs.doneMany#one":`{count} project added`,"packs.all":`Install all`,"packs.choose":`Choose`,"packs.none":`None`,"import.title":`Import from another agent`,"import.desc":`Hermes, Claude Code, OpenClaw or any other agent: it exports what it knows about you as projects and topics, you drop the zip here. Nothing existing is overwritten.`,"import.agent":`Your current agent`,"import.other":`Other`,"import.step1":`Copy this prompt and send it to your current agent. It builds a zip with your projects, topics, memory and skills.`,"import.step2":`Drop the zip it gives you (or click to choose it). You will see what it contains before anything is imported.`,"import.drop":`Drop the .zip here, or click to choose it`,"import.reading":`Reading the zip…`,"import.projects":`projects`,"import.topics":`topics`,"import.skills":`Skills`,"import.files":`files · {size}`,"import.new":`new`,"import.merge":`exists - merged`,"import.rootMemory":`Your profile and preferences (workspace memory)`,"import.aside":`Kept for Harness`,"import.neverOverwrite":`Existing memory files get an “Imported” section added, other existing files are kept and the imported copy is saved next to them.`,"import.secrets":`{count} files refused: they contain a key or a token`,"import.secretsHint":`Add your keys in Settings → Keys instead - never in memory files.`,"import.skipped":`{count} files skipped`,"import.apply":`Import`,"import.done":`Imported: {projects} projects, {topics} topics, {files} files.`,"import.mergedInto":`{count} existing memory files received an “Imported” section.`,"import.finish":`Let Harness finish the import`,"import.finishTitle":`Finish the import`,"import.finishHint":`Harness tidies the imported memory, creates your tasks, proposes your scheduled jobs and lists the keys to add.`,"import.finishing":`Harness is finishing the import (tasks, scheduled jobs, keys to add) - you will find it in Sessions.`,"import.copy":`Copy the prompt`,"import.copied":`Copied`,"import.skillsN":`skills`,"trash.loadFailed":`Could not load the trash`,"trash.loadFailedDesc":`Check your connection or access permissions, then retry.`,"telegram.threads":`Threads`,"telegram.threadsDesc":`One per open session, kept in sync automatically. Deleting a thread in Telegram archives its session (nothing is lost).`,"telegram.mirrorWeb":`Show web conversations in Telegram`,"telegram.mirrorWebDesc":`What you write in the web UI and Harness's answers also appear in the session's thread, silently (the bell of a session makes its answers ring).`,"telegram.threadDays":`Keep a thread for`,"telegram.threadDaysDesc":`Open sessions idle for longer lose their thread (they stay in the web UI and come back on the next message).`,"telegram.days":`{count} days`,"telegram.thread.session":`session`,"telegram.sync":`Sync threads`,"telegram.unlink":`Disconnect Telegram`,"telegram.unlinkDesc":`Forgets the bot token, the linked chat and the threads. Sessions stay in the web UI.`,"telegram.unlinkConfirm":`Disconnect Telegram?`,"backup.whyTitle":`Why back up?`,"backup.why":`Your memory files are what makes Harness useful over time. If this server dies, a backup lets the installer restore them on a new one in a minute. Only a whitelist of text files is pushed and a secret scanner blocks anything that looks like a key.`,"backup.gh1":`Create a fine-grained token at`,"backup.gh2":`Repository access: "All repositories" if you want the repository created for you, otherwise only the backup repository.`,"backup.gh3":`Permissions:`,"backup.gh3b":`(the latter only to create the repository).`,"backup.gh4":`Generate the token, copy it and paste it below.`,"backup.repo":`Repository`,"backup.repoHint":`owner/name — it must be private.`,"backup.repoInvalid":`Use the form owner/name.`,"backup.token":`GitHub token`,"backup.tokenRequired":`Paste the GitHub token.`,"backup.create":`Create the private repository for me`,"backup.createHint":`If it does not exist yet. Requires the Administration permission.`,"backup.connect":`Verify and save`,"backup.configFailed":`GitHub refused the access.`,"backup.notPrivate":`This repository is public: the backup refuses to push to it.`,"backup.connected":`Backup repository connected`,"backup.private":`Private`,"backup.runFirst":`Run the first backup`,"backup.runNow":`Back up now`,"backup.runOk":`Backup complete`,"backup.runOkDesc":`{files} files, commit {commit}.`,"backup.runFailed":`Backup failed`,"backup.repository":`Repository`,"backup.repositoryDesc":`Where your memory is pushed.`,"backup.settings":`Schedule & content`,"backup.schedule":`Schedule`,"backup.scheduleHint":`Cron expression, in your time zone.`,"backup.scheduleInvalid":`Invalid cron expression.`,"backup.include":`Included files`,"backup.includeHint":`Grey patterns are always included. Add globs relative to the workspace.`,"backup.always":`Always included`,"backup.addGlob":`Add a pattern`,"backup.history":`History`,"backup.historyDesc":`Restoring saves the current files to the trash first.`,"backup.noHistory":`No backup yet`,"backup.noHistoryDesc":`Runs appear here.`,"backup.filesCount":`{count} files`,"backup.filesCount#one":`{count} file`,"backup.changedCount":`{count} changed`,"backup.restore":`Restore`,"backup.restoreTitle":`Restore this backup?`,"backup.restoreDesc":`Whitelisted files, cron jobs and settings are replaced by this version. Current files are moved to the trash first.`,"backup.restored":`{count} files restored`,"backup.restored#one":`{count} file restored`,"backup.forget":`Disconnect backup`,"backup.forgetDesc":`Forgets the repository and the token. The repository itself is not deleted.`,"backup.forgetConfirm":`Disconnect the backup?`,"mcp.whatTitle":`MCP servers give Claude new tools`,"pc.candidateTitle":`{name} wants to connect`,"pc.candidateFrom":`It connected from {ip} at {time}. If that is not your computer's address, refuse.`,"pc.candidateDesc":`A {os} computer used your download. Is it yours? Until you say yes, Claude cannot use it. If you do not recognise it, refuse: it is disconnected and forgets this server.`,"pc.candidateYes":`Yes, it is my PC`,"pc.candidateNo":`Refuse`,"pc.title":`Browser of my PC`,"pc.desc":`Let Claude use a browser on your own computer: a separate profile of your browser, opened only while Claude needs it.`,"pc.whichOs":`Your computer`,"pc.whichBrowser":`Browser Claude will use`,"pc.isolated":`Claude gets its own {browser} profile: your usual tabs, passwords and history are never touched. Sign in to sites there once if Claude needs them.`,"pc.autostart":`Start with the computer`,"pc.autostartDesc":`Harness PC waits in the background (almost no CPU or memory) and opens the browser only when Claude needs it. Off: start it yourself when you want Claude to browse.`,"pc.prepare":`Get Harness PC`,"pc.step.downloadWin":`Download HarnessPC.exe (it is already linked to this server).`,"pc.step.download":`Download Harness PC (it is already linked to this server).`,"pc.step.runWin":`Open it from your Downloads. If Windows shows "Windows protected your PC", click More info, then Run anyway.`,"pc.step.run":`Run it (or paste the command below in a terminal).`,"pc.step.wait":`This page then asks you to confirm it is your PC. {browser} opens only when Claude uses it.`,"pc.downloadWin":`Download for Windows`,"pc.downloadLinux":`Download for Linux`,"pc.downloadMacArm":`Download for Mac (Apple chip)`,"pc.downloadMacIntel":`Mac with Intel chip`,"pc.orCommandWin":`Or paste this in PowerShell:`,"pc.orCommand":`Or paste this in a terminal:`,"pc.smartscreenTitle":`Windows may warn about it`,"pc.smartscreen":`Harness PC is not signed by a publisher yet, so SmartScreen asks for confirmation: More info, then Run anyway. It needs no administrator rights and only opens the browser you chose.`,"pc.waiting":`Waiting for your PC… (link valid {left})`,"pc.expired":`This download expired: get a new one.`,"pc.connected":`{name} is connected`,"pc.computer":`Computer`,"pc.state":`State`,"pc.lastUse":`Last used`,"pc.never":`never`,"pc.offline":`Offline`,"pc.ready":`Ready (browser closed)`,"pc.inUse":`{browser} open for Claude`,"pc.offlineTitle":`Your PC is not connected`,"pc.offlineDesc":`Harness PC is not running, or the computer is off or asleep. Start Harness PC on it; Claude is told the PC is offline meanwhile.`,"pc.mcpMissing":`Claude does not see the browser tools yet: reload this page in a moment; if it stays, use Reinstall.`,"pc.test":`Test`,"pc.testOk":`The browser of your PC answered`,"pc.testFail":`The browser did not answer`,"pc.stop":`Stop now`,"pc.wipe":`Erase the profile`,"pc.wipeConfirm":`Erase the profile Claude uses?`,"pc.wipeDesc":`Its cookies, sign-ins and history on your PC are deleted. Your usual browser is not touched.`,"pc.wiped":`Profile erased`,"pc.reinstall":`Reinstall / other PC`,"pc.unpair":`Disconnect`,"pc.unpairConfirm":`Disconnect this PC?`,"pc.unpairDesc":`Harness PC stops and removes itself from startup; Claude loses the browser tools. The profile stays on the PC until you erase it.`,"pc.idle":`Close the browser after`,"pc.idleDesc":`Without any browser action from Claude for this long, the browser and its tools stop.`,"pc.recent":`Recent actions`,"mcp.whatExplain":'A server added for "Every session" is available everywhere; one added to a topic only in the sessions of that topic. Secrets stay in Settings → Keys and are referenced as ${KEY_NAME}. You can also just ask Claude in a topic: "connect the MCP …".',"mcp.servers":`MCP servers`,"mcp.serversDesc":`The servers Claude Code loads in this workspace.`,"mcp.checkedAt":`States checked {when}.`,"mcp.check":`Check`,"mcp.checking":`Checking…`,"mcp.add":`Add a server`,"mcp.addDesc":`The address (or command) comes from the documentation of the service.`,"mcp.empty":`No MCP server`,"mcp.emptyDesc":`Add one here, or ask Claude in the topic that needs it.`,"mcp.name":`Name`,"mcp.where":`Where`,"mcp.whereHint":`Every session, or only the sessions of one topic.`,"mcp.searchTopic":`Search a topic`,"mcp.everywhere":`Every session`,"mcp.stateCol":`State`,"mcp.type":`Type`,"mcp.typeHttp":`Address (URL)`,"mcp.typeStdio":`Local program`,"mcp.url":`Address`,"mcp.command":`Command`,"mcp.headers":`Headers (optional)`,"mcp.env":`Environment variables (optional)`,"mcp.addLine":`Add a line`,"mcp.insertKey":`Insert a key of the vault`,"mcp.noKeys":`No key in Settings → Keys`,"mcp.keysHint":'A key written as ${KEY_NAME} is read from the vault when the session starts (it is made available to sessions automatically). Servers with a "Connect" button need no key.',"mcp.literalWarn":"This looks like a token written in clear: better put it in Settings → Keys and use ${KEY_NAME}.","mcp.literal":`token in clear`,"mcp.nameInvalid":`Letters, digits, ".", "_" and "-" only.`,"mcp.urlInvalid":`The address starts with https://`,"mcp.commandRequired":`Enter the command that starts the server.`,"mcp.added":`{name} added`,"mcp.addedExposed":`{name} added - keys now given to sessions: {keys}`,"mcp.state.connected":`Connected`,"mcp.state.needs_auth":`To connect`,"mcp.state.failed":`Error`,"mcp.state.pending":`To approve`,"mcp.state.unknown":`Not checked`,"mcp.connect":`Connect`,"mcp.reconnect":`Reconnect`,"mcp.connectTitle":`Connect {name}`,"mcp.connectDesc":`Once, in four steps: the connection is then kept for every session.`,"mcp.preparing":`Preparing the sign-in page…`,"mcp.step1":`Open the sign-in page of the service`,"mcp.openLogin":`Open the sign-in page`,"mcp.step2":`Sign in at {service} and accept`,"mcp.step3":`You land on an error page: that is expected`,"mcp.step3Desc":`The service sends you back to an address of the Harness server ("localhost") that your browser cannot open, so it shows "This site can’t be reached". The connection is not finished yet: the code is in the address.`,"mcp.browserError":`This site can’t be reached - localhost refused to connect.`,"mcp.step3Copy":`Copy the whole address from the address bar (click it, then Ctrl+C / ⌘C). On a phone: long press on the address, Copy.`,"mcp.step4":`Come back here and paste it`,"mcp.paste":`Paste`,"mcp.pasteDenied":`The browser refused: paste with Ctrl+V / ⌘V in the field.`,"mcp.noCode":`This address has no "code=": copy the address of the error page, after accepting.`,"mcp.whyTitle":`Why this copy-paste?`,"mcp.whyBody":`Claude Code, which runs on your server, waits for the service’s answer on a local address of the server. The service can only send your browser to that address, which only exists on the server. By pasting it, you hand the code to Claude Code, which finishes the connection. It works whatever the access (domain, Tailscale) and nothing else is needed. Do it within a few minutes: the code expires.`,"mcp.finish":`Finish`,"mcp.retry":`Try again`,"mcp.connected":`{name} is connected`,"mcp.chatHint":`The agent needs this connection. Once done, tell it to try again.`,"mcp.chatConnected":`{name} was connected at the last check: connect it again if the agent still asks.`,"mcp.remove":`Remove`,"mcp.removeTitle":`Remove {name}?`,"mcp.removeDesc":`Claude will no longer have its tools there. The keys of the vault are kept.`,"keys.vault":`Vault`,"keys.vaultDesc":`Values never leave the server unless you reveal them.`,"keys.add":`Add key`,"keys.edit":`Edit key`,"keys.dialogDesc":`Stored in the server secrets file (mode 600).`,"keys.name":`Name`,"keys.nameHint":`Environment-variable style: OPENAI_API_KEY.`,"keys.nameInvalid":`Letters, digits and underscores, starting with a letter.`,"keys.value":`Value`,"keys.valueKeep":`Leave empty to keep the current value.`,"keys.valueRequired":`Enter a value.`,"keys.note":`Note`,"keys.notePlaceholder":`What it is for, where it comes from`,"keys.noNote":`No note`,"keys.expose":`Expose to Harness sessions`,"keys.exposeShort":`Exposed`,"keys.unexpose":`Stop exposing`,"keys.exposeDesc":`Exported as an environment variable in every Harness turn.`,"keys.exposeTitle":`Exposed keys`,"keys.exposeExplain":`An exposed key is available to Harness as an environment variable (e.g. $OPENAI_API_KEY) in every session and cron, so scripts can use it without the value ever appearing in a prompt. Harness can still read it: expose only what sessions need.`,"keys.reveal":`Reveal`,"keys.copied":`{name} copied`,"keys.added":`Key added`,"keys.updated":`Key updated`,"keys.deleteTitle":`Delete {name}?`,"keys.deleteDesc":`Scripts and sessions that use it will stop working.`,"keys.empty":`No keys yet`,"keys.emptyDesc":`Store API keys and tokens here instead of in files.`,"features.git":`Git & GitHub page`,"features.gitDesc":`A "Git" entry in the sidebar: every repository of the server and of your GitHub account with your rights, their branches and commits as a graph. The graphs in conversations stay either way. For GitHub, add the GITHUB_TOKEN key in`,"features.infra":`Infra page`,"features.infraDesc":`An "Infra" entry in the sidebar: every site, database, bucket, domain and server - this server, your other servers (SSH), Cloudflare, Hostinger - with its status, its links and where it lives. Read-only; Claude creates sites, databases and buckets the standard way. For Cloudflare and Hostinger, add their keys in`,"system.health":`Health`,"system.healthDesc":`Refreshed every 30 seconds.`,"system.claudeAuth":`Claude authentication`,"system.notConnected":`Not connected`,"system.backupAge":`Last backup`,"system.never":`Never`,"system.hoursAgo":`{n} h ago`,"system.failedLogins":`Failed sign-ins (1 h)`,"system.load":`Load average`,"system.services":`Services`,"system.servicesDesc":`systemd units that matter for Harness Maxxing.`,"system.disabled":`Disabled`,"system.start":`Start`,"system.stop":`Stop`,"system.restart":`Restart`,"system.stopTitle":`Stop {name}?`,"system.restartTitle":`Restart {name}?`,"system.serviceConfirm":`Running work handled by this service may be interrupted.`,"system.selfRestart":`The UI goes offline for a few seconds and reconnects by itself. Running Harness turns are not affected.`,"system.actionDone":`{name}: done`,"system.logs":`Logs`,"system.unit":`Service`,"system.lines":`{n} lines`,"system.linesLabel":`Number of lines`,"system.noLogs":`No log lines.`,"system.version":`Version`,"system.upToDate":`Up to date`,"system.behind":`{n} updates available`,"system.unknownLatest":`Latest version unknown`,"system.unknownLatestDesc":"GitHub could not be reached with the update token. Run `maxxing update --check` on the server to see why (expired token, no network).","system.check":`Check now`,"system.checkFailed":`The check failed`,"system.checkedAt":`checked {when}`,"system.update":`Update now`,"system.updateTitle":`Update Harness Maxxing?`,"system.updateDesc":`Downloads the new version, installs dependencies and restarts the service (about a minute). Your data, workspace and extensions are kept.`,"system.updating":`Updating…`,"system.restarting":`Restarting the server…`,"system.updated":`Update installed`,"system.autoUpdate":`Update by itself when nobody is here`,"system.autoUpdateHint":`Off by default. On: when a new version is out and nobody is on the interface, nothing is running (no turn, no job, nothing for 10 minutes) and the update would not touch your customizations, Harness updates itself, then restarts for a few seconds. Otherwise it waits and tells you in the notifications.`,"system.updatedDesc":`Reload the page to use the new version.`,"system.customs":`{count} customizations of the product code, carried over by every update`,"system.customs#one":`{count} customization of the product code, carried over by every update`,"system.license":`License {key} ({kind}) - {email}`,"system.licenseKind.paid":`paid`,"system.licenseKind.beta":`beta`,"system.licenseKind.gift":`gift`,"system.licenseKind.enterprise":`enterprise`,"system.licenseUpdatesUntil":`updates until {date}`,"system.licenseUpdatesEnded":`updates ended on {date} - this server keeps working on its version`,"system.licenseUpdatesForever":`updates included`,"system.licenseMoving":`Moving to the GitHub updates is pending: {error}. Tried again every 6 h.`,"system.movedToGit":`Updates from GitHub (stable branch) since {date}, like every install. Key {key} kept.`,"system.pendingConflict":`Update {version} waits for Harness`,"system.pendingConflictDesc":`Your customizations conflict with the new version. Nothing changed: the current version keeps running. Harness can adapt them in the system project (topic harness).`,"system.pendingRolledBack":`Update {version} was rolled back`,"system.pendingRolledBackDesc":`The new version did not start, so the previous one was restored automatically - nothing lost. Ask Harness in the system project (topic harness) to look into it.`,"system.askClaude":`Ask Harness`,"memory.title":`Second brain cleaner`,"memory.desc":`Keeps every memory.md short and well ordered: duplicates merged, contradictions settled, old history summarised, sections sorted. Runs every night (job "Memory compaction") and on demand.`,"memory.cleanNow":`Clean now`,"memory.limit":`Maximum length per file`,"memory.limitDesc":`Files longer than this are compacted and reorganised to fit (about 80 % of it, to leave room).`,"memory.lines":`{count} lines`,"memory.noLimit":`No limit`,"memory.daily":`Nightly clean`,"memory.dailyDesc":`The "Memory compaction" job runs at 5:00 by default: change its time or turn it off in Crons.`,"memory.openCrons":`Open Crons`,"memory.files":`Memory files`,"memory.filesDesc":`Every memory.md of the workspace.`,"memory.overCount":`{count} files over {limit} lines - "Clean now" fixes them.`,"memory.overCount#one":`1 file over {limit} lines - "Clean now" fixes it.`,"memory.allUnder":`Every file is under {limit} lines.`,"memory.none":`No memory file yet`,"memory.file":`File`,"memory.lineCount":`Lines`,"memory.size":`Size`,"memory.started":`Clean-up started`,"memory.startedDesc":`Harness is compacting the memory files in a new session.`,"stats.quota":`Claude plan usage`,"stats.quotaDesc":`How much of your Claude subscription limits you have used (5-hour window and week).`,"stats.quotaEnable":`Show plan usage`,"stats.quotaEnableDesc":`Experimental: read from an undocumented Anthropic endpoint, may stop working. Also adds the dashboard widget.`,"stats.fiveHour":`Current 5-hour window`,"stats.sevenDay":`This week`,"stats.resets":`resets {at}`,"stats.stale":`Last known values (the endpoint did not answer just now).`,"stats.quotaUnavailable":`Plan usage is not available with this sign-in method.`,"stats.reason.no_oauth_credentials":`Sign Claude in on this server (Settings -> Claude) to read the plan usage.`,"stats.reason.api_key":`Plan usage exists only for a Claude subscription; this server uses an API key.`,"stats.reason.rate_limited":`Anthropic limits how often the usage can be read - next reading {when}.`,"stats.reason.http_401":`The Claude sign-in was refused: sign in again (Settings -> Claude).`,"stats.reason.other":`Plan usage could not be read ({code}).`,"stats.nextReading":`Next reading {when}.`,"stats.tokens":`Tokens`,"stats.tokensDesc":`Counted from every Harness turn, archived sessions included. The daily chart starts with this version.`,"stats.empty":`No Harness turn yet`,"stats.total":`Tokens`,"stats.turns":`{count} turns`,"stats.turns#one":`1 turn`,"stats.turnsCol":`Turns`,"stats.inOut":`Input / output`,"stats.cache":`Cache read / write`,"stats.cacheHint":`cheap context re-reads`,"stats.turnStart":`Turn start (median)`,"stats.turnStartHint":`first answer after {first} s · last {count} turns`,"stats.cost":`Cost`,"stats.costHint":`API price equivalent (a subscription is not billed per token)`,"stats.perDay":`Tokens per day (30 days)`,"stats.groupBy":`Group by`,"stats.byProject":`Project`,"stats.byTopic":`Topic`,"stats.bySession":`Session`};export{e as default};